// StartRun: reads the wall clock once and reports the UTC date and the
// instant (Unix seconds) at which the run began.
//
// Capability: only `wasi:clocks/wall-clock@0.2.0` is imported, matching the
// node's `with Clock` grant. No HTTP import is present; see the note in the
// accompanying message about the unapproved `aap:caps/http-client` grant.

wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::wasi::clocks::wall_clock;

struct Node;

/// Converts days since 1970-01-01 into a proleptic Gregorian (year, month, day).
/// Uses Howard Hinnant's `civil_from_days` algorithm, with signed arithmetic
/// throughout so the era computation is correct for all inputs.
fn civil_from_days(days: i64) -> (i64, u32, u32) {
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097; // [0, 146096]
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365; // [0, 399]
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100); // [0, 365]
    let mp = (5 * doy + 2) / 153; // [0, 11], March-based
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32; // [1, 31]
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32; // [1, 12]
    let y = yoe + era * 400 + if m <= 2 { 1 } else { 0 };
    (y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started = now.seconds;

        let days = (started / 86_400) as i64;
        let (y, m, d) = civil_from_days(days);

        // The contract requires exactly 10 characters, which is YYYY-MM-DD.
        // Years outside 0..=9999 cannot be written in that form, so they are
        // clamped to the last representable date. The clock cannot reach that
        // range in practice, but the output must satisfy the ensures clause.
        let date = if (0..=9999).contains(&y) {
            format!("{:04}-{:02}-{:02}", y, m, d)
        } else {
            "9999-12-31".to_string()
        };

        RunInfo { date, started }
    }
}

export!(Node);
```

